/* Custom map backgrounds framework.
 * Includes generated per-map data and dispatch tables.
 * The generated .inc files are produced by tools/build_custom_maps.py
 * from tools/custom_map_manifest.json. */
#include "global.h"
#include "configs/runtime.h"
#include "overworld.h"

/* Runtime flags live in IWRAM (asm/ram_map_iwram.s).
 * Extern declarations are in include/maps_custom.h. */

/* Per-map asset includes — generated by build_custom_maps.py.
 * Each map gets: tileset, ground_tilemap, [roof_tilemap,] palette, collision. */
#include "src_custom/generated/maps/custom_map_dispatch.inc"

/* Override tables for collision, connection, spawn, map sources. */
#include "src_custom/generated/maps/manifest_collision_overrides.inc"
#include "src_custom/generated/maps/manifest_connection_overrides.inc"
#include "src_custom/generated/maps/manifest_map_sources.inc"
#include "src_custom/generated/maps/manifest_spawn_overrides.inc"

/* MapData dummy provider for custom maps (no NPCs — uses event scripts). */
const struct MapData *GetCustomMapData(u16 mapId) {
    (void)mapId;
    return NULL;
}

/* Collision pointer provider for custom maps. */
const u16 *GetCustomMapCollision(u16 mapId) {
#if CUSTOM_MAP_COUNT > 0
    u16 idx = mapId - CUSTOM_MAP_BASE;
    if (idx < CUSTOM_MAP_COUNT)
        return sCustomCollisions[idx];
#endif
    return NULL;
}

/* Tileset provider for custom maps — returns LZ77-compressed data. */
const u8 *GetCustomMapTileset(u16 mapId) {
#if CUSTOM_MAP_COUNT > 0
    u16 idx = mapId - CUSTOM_MAP_BASE;
    if (idx < CUSTOM_MAP_COUNT)
        return sCustomTilesets[idx];
#endif
    return NULL;
}

/* Ground tilemap provider for custom maps. */
const u16 *GetCustomMapGroundTilemap(u16 mapId) {
#if CUSTOM_MAP_COUNT > 0
    u16 idx = mapId - CUSTOM_MAP_BASE;
    if (idx < CUSTOM_MAP_COUNT)
        return sCustomGroundTilemaps[idx];
#endif
    return NULL;
}

/* Roof tilemap provider for custom maps (returns NULL if no roof). */
const u16 *GetCustomMapRoofTilemap(u16 mapId) {
#if CUSTOM_MAP_COUNT > 0
    u16 idx = mapId - CUSTOM_MAP_BASE;
    if (idx < CUSTOM_MAP_COUNT)
        return sCustomRoofTilemaps[idx];
#endif
    return NULL;
}

/* Palette provider for custom maps. */
const u16 *GetCustomMapPalette(u16 mapId) {
#if CUSTOM_MAP_COUNT > 0
    u16 idx = mapId - CUSTOM_MAP_BASE;
    if (idx < CUSTOM_MAP_COUNT)
        return sCustomPalettes[idx];
#endif
    return NULL;
}

/* Music ID for a custom map. */
u16 GetCustomMapMusic(u16 mapId) {
    (void)mapId;
    return 1; /* default overworld track */
}
